5	/// Registers the `capture` feature into the project's single `get_it`
6	/// instance (`sl`). Unlike every other feature's cubit in this codebase
7	/// (`AccountSettingsCubit`/`AuthCubit`, lazy singletons), [TextEntryCubit]
8	/// is a **factory** — the Insertion Modal needs a fresh instance per "+"
9	/// tap (Boundaries: "Modal open resets"), not one long-lived instance
10	/// reused across opens. Called from `setupCoreDependencies()` right after
11	/// `registerEntriesFeature()` (Code Map).
12	void registerCaptureFeature() {
13	  sl.registerFactory<TextEntryCubit>(
14	    () => TextEntryCubit(sl<EntriesRepository>()),
15	  );
16	}
