7	/// `POST /entries`'s response `data` object (`openapi.yaml:370-456`) —
8	/// decodes exactly the 8 fields [Entry] models (Code Map/Boundaries);
9	/// every other field (`tags`/`piiStatus`/`piiSpans`/`embeddingStatus`/
10	/// `mediaDurationSeconds`) is simply ignored by `json_serializable`'s
11	/// generated `fromJson`, same convention `AccountSettingsDto` already
12	/// uses for the fields it doesn't model.
13	///
14	/// [source] serializes/deserializes against [EntrySource]'s own `.name`
15	/// (`json_serializable`'s default enum handling) — the enum's member
16	/// names already match the backend's lowercase `manual`/`audio`/`photo`/
17	/// `chat` strings exactly, so no `@JsonValue` overrides are needed.
18	@JsonSerializable()
19	class EntryDto {
20	  const EntryDto({
21	    required this.id,
22	    required this.content,
23	    required this.source,
24	    required this.chatMessageId,
25	    required this.occurredAt,
26	    required this.serverRevision,
27	    required this.createdAt,
28	    required this.updatedAt,
29	  });
30	
31	  final String id;
32	  final String content;
33	  final EntrySource source;
34	  final String? chatMessageId;
35	  final String occurredAt;
36	  final int serverRevision;
37	  final String createdAt;
38	  final String updatedAt;
39	
40	  factory EntryDto.fromJson(Map<String, dynamic> json) =>
41	      _$EntryDtoFromJson(json);
42	
43	  /// Also the exact shape written to the `entries` Hive box (Design
44	  /// Notes: "raw `Map<String, dynamic>` via `EntryDto.toJson()`").
45	  Map<String, dynamic> toJson() => _$EntryDtoToJson(this);
46	}
