8	/// The entries feature's one write call so far (`entries-create`) — posts
9	/// via the shared `ApiClient`, mirroring `account_remote_data_source.dart`'s
10	/// pattern.
11	class EntriesRemoteDataSource {
12	  EntriesRemoteDataSource(this._apiClient);
13	
14	  final ApiClient _apiClient;
15	
16	  /// Sends exactly `{content, source}` — this story never passes
17	  /// `chatMessageId`/`occurredAt`/`mediaDurationSeconds` (Boundaries: no
18	  /// `Entry` field beyond the modeled 8; those three are optional in the
19	  /// contract and belong to later stories/epics).
20	  Future<Either<Failure, EntryDto>> create({
21	    required String content,
22	    required EntrySource source,
23	  }) async {
24	    final result = await _apiClient.post(
25	      'entries-create',
26	      data: {'content': content, 'source': source.name},
27	    );
28	    return result.flatMap((json) {
29	      try {
30	        final data = json['data'] as Map<String, dynamic>;
31	        return right(EntryDto.fromJson(data));
32	      } catch (error) {
33	        // A 200 response that doesn't match the expected shape is a
34	        // client-side parse failure, never a backend-sent code — maps to
35	        // the local-only `malformedResponse` (RNF09: no exception escapes
36	        // unmapped).
37	        return left(Failure.malformedResponse(message: error.toString()));
38	      }
39	    });
40	  }
41	}
