14	/// On success, writes the entry through to the `entries` Hive box (`Box
15	/// <Map>`, keyed by id, raw `EntryDto.toJson()` — Design Notes) *before*
16	/// returning `right(...)`, same "persist then return" ordering
17	/// `AuthRepositoryImpl._authenticate` already uses for its own
18	/// post-success side effect.
19	class EntriesRepositoryImpl implements EntriesRepository {
20	  EntriesRepositoryImpl({
21	    required EntriesRemoteDataSource remoteDataSource,
22	    required Box<Map> entriesBox,
23	  }) : _remoteDataSource = remoteDataSource,
24	       _entriesBox = entriesBox;
25	
26	  final EntriesRemoteDataSource _remoteDataSource;
27	  final Box<Map> _entriesBox;
28	
29	  @override
30	  Future<Either<Failure, Entry>> create({
31	    required String content,
32	    required EntrySource source,
33	  }) async {
34	    final result = await _remoteDataSource.create(
35	      content: content,
36	      source: source,
37	    );
38	    return result.match((failure) async => left(failure), (dto) async {
39	      // A thrown Hive/disk exception must never escape unmapped (RNF09) —
40	      // same rationale/fallback `AuthRepositoryImpl` already uses for its
41	      // own local-persistence step.
42	      try {
43	        await _entriesBox.put(dto.id, dto.toJson());
44	      } catch (error) {
45	        return left(Failure.malformedResponse(message: error.toString()));
46	      }
47	      return right(_toEntry(dto));
48	    });
49	  }
50	
51	  Entry _toEntry(EntryDto dto) => Entry(
52	    id: dto.id,
53	    content: dto.content,
54	    source: dto.source,
55	    chatMessageId: dto.chatMessageId,
56	    occurredAt: dto.occurredAt,
57	    serverRevision: dto.serverRevision,
58	    createdAt: dto.createdAt,
59	    updatedAt: dto.updatedAt,
60	  );
61	}
