1	import 'package:flutter/foundation.dart';
2	import 'package:path_provider/path_provider.dart';
3	import 'package:universal_io/io.dart';
4	import 'package:whisper_ggml/src/models/whisper_model.dart';
5	
6	import 'models/whisper_result.dart';
7	import 'whisper.dart';
8	import 'whisper_live.dart';
9	
10	class WhisperController {
11	  String _modelPath = '';
12	  String? _dir;
13	
14	  Future<void> initModel(WhisperModel model) async {
15	    _dir ??= await getModelDir();
16	    _modelPath = '$_dir/ggml-${model.modelName}.bin';
17	  }
18	
19	  /// Start a live transcription session.
20	  ///
21	  /// Provide exactly one of [model] and [modelPath]: [model] resolves to the
22	  /// standard download location (see [getPath]), while [modelPath] runs the
23	  /// session against any local ggml model file.
24	  ///
25	  /// [pcm16Stream] must produce 16 kHz mono little-endian PCM16 audio (e.g.
26	  /// the `record` package's `startStream` with
27	  /// `RecordConfig(encoder: AudioEncoder.pcm16bits, sampleRate: 16000,
28	  /// numChannels: 1)`). Partial transcripts are emitted on
29	  /// [WhisperLiveSession.partials] while audio flows; when [pcm16Stream]
30	  /// closes (or [WhisperLiveSession.stop] is called) the session finalizes
31	  /// and `stop()` returns the full transcript.
32	  ///
33	  /// Unlike [transcribe], the model is loaded once for the whole session.
34	  /// The `gate*` parameters tune the native energy gate that keeps silence
35	  /// away from the decoder: a chunk counts as voiced when its RMS exceeds
36	  /// `max(gateVoiceRatio * noiseFloor, gateRmsMin)`, where the adaptive
37	  /// noise floor is capped at [gateNoiseFloorCap]. Raise the cap for loud
38	  /// environments; lower [gateRmsMin] for very quiet speakers.
39	  ///
40	  /// [keepModelLoaded] parks the model in native memory when the session
41	  /// stops, so the next session (or one-shot [transcribe]) with the same
42	  /// model skips the multi-second load — see
43	  /// [TranscribeRequest.keepModelLoaded]. Release it with [releaseModel].
44	  Future<WhisperLiveSession> transcribeLive({
45	    WhisperModel? model,
46	    String? modelPath,
47	    required Stream<Uint8List> pcm16Stream,
48	    String lang = 'en',
49	    String? initialPrompt,
50	    bool suppressNonSpeechTokens = false,
51	    bool keepModelLoaded = false,
52	    double gateRmsMin = 0.0015,
53	    double gateVoiceRatio = 2.5,
54	    double gateNoiseFloorCap = 0.01,
55	  }) async {
56	    if ((model == null) == (modelPath == null)) {
57	      throw ArgumentError('Provide exactly one of model or modelPath.');
58	    }
59	    if (model != null) {
60	      await initModel(model);
61	    }
62	
63	    final WhisperLiveSession session = await startWhisperLiveSession(
64	      modelPath: modelPath ?? _modelPath,
65	      lang: lang,
66	      initialPrompt: initialPrompt,
67	      suppressNonSpeechTokens: suppressNonSpeechTokens,
68	      keepModelLoaded: keepModelLoaded,
69	      gateRmsMin: gateRmsMin,
70	      gateVoiceRatio: gateVoiceRatio,
71	      gateNoiseFloorCap: gateNoiseFloorCap,
72	    );
73	
74	    pcm16Stream.listen(
75	      session.feed,
76	      onDone: session.stop,
77	      onError: (Object e) {
78	        debugPrint('transcribeLive: audio stream error: $e');
79	        session.stop();
80	      },
81	    );
82	
83	    return session;
84	  }
85	
86	  /// Transcribe [audioPath] with [model].
87	  ///
88	  /// When [withSegments] is `true`, the result's
89	  /// [WhisperTranscribeResponse.segments] carries per-segment timestamps
90	  /// (`fromTs`/`toTs`) alongside the text; combine with [splitOnWord] to
91	  /// get one segment per word instead of per phrase.
92	  ///
93	  /// [diarize] enables tinydiarize speaker-turn detection: with a `-tdrz`
94	  /// model ([WhisperModel.smallEnTdrz], English only) and [withSegments],
95	  /// segments where the speaker changes afterwards have
96	  /// `speakerTurnNext == true`. Has no effect with regular models.
97	  ///
98	  /// [onProgress] reports transcription progress as a 0–100 percentage
99	  /// (coarse steps) while inference runs.
100	  ///
101	  /// [keepModelLoaded] keeps the model resident in native memory after the
102	  /// request, so the next transcription with the same model skips the
103	  /// multi-second load — see [TranscribeRequest.keepModelLoaded]. Release
104	  /// it with [releaseModel].
105	  ///
106	  /// [vadModelPath] enables whisper.cpp's built-in Silero VAD, trimming
107	  /// non-speech before decoding; [vadSpeechPadMs] overrides the padding
108	  /// kept around detected speech — see [TranscribeRequest.vadModelPath].
109	  ///
110	  /// [maxContext] bounds how much earlier text conditions each following
111	  /// 30-second window; `0` stops a hallucinated phrase from repeating
112	  /// across a long recording — see [TranscribeRequest.maxContext].
113	  Future<TranscribeResult?> transcribe({
114	    required WhisperModel model,
115	    required String audioPath,
116	    String lang = 'en',
117	    bool diarize = false,
118	    String? initialPrompt,
119	    bool noContext = false,
120	    int? maxContext,
121	    bool suppressNonSpeechTokens = false,
122	    bool withSegments = false,
123	    bool splitOnWord = false,
124	    bool keepModelLoaded = false,
125	    String? vadModelPath,
126	    int? vadSpeechPadMs,
127	    void Function(int percent)? onProgress,
128	  }) async {
129	    await initModel(model);
130	
131	    final Whisper whisper = Whisper(model: model);
132	    final DateTime start = DateTime.now();
133	    const bool translate = false;
134	
135	    try {
136	      final WhisperTranscribeResponse transcription = await whisper.transcribe(
137	        transcribeRequest: TranscribeRequest(
138	          audio: audioPath,
139	          language: lang,
140	          isTranslate: translate,
141	          isNoTimestamps: !withSegments,
142	          splitOnWord: splitOnWord,
143	          isRealtime: true,
144	          diarize: diarize,
145	          initialPrompt: initialPrompt,
146	          noContext: noContext,
147	          maxContext: maxContext,
148	          suppressNonSpeechTokens: suppressNonSpeechTokens,
149	          keepModelLoaded: keepModelLoaded,
150	          vadModelPath: vadModelPath,
151	          vadSpeechPadMs: vadSpeechPadMs,
152	        ),
153	        modelPath: _modelPath,
154	        onProgress: onProgress,
155	      );
156	
157	      final Duration transcriptionDuration = DateTime.now().difference(start);
158	
159	      return TranscribeResult(
160	        time: transcriptionDuration,
161	        transcription: transcription,
162	      );
163	    } catch (e) {
164	      debugPrint(e.toString());
165	      return null;
166	    }
167	  }
168	
169	  /// Free the model parked in native memory by a transcription with
170	  /// `keepModelLoaded: true`. Safe to call when nothing is parked.
171	  Future<void> releaseModel() {
172	    // Which model the Whisper instance was created with is irrelevant here:
173	    // the native side frees whatever model is parked.
174	    return const Whisper(model: WhisperModel.tiny).releaseModel();
175	  }
176	
177	  static Future<String> getModelDir() async {
178	    if (!Platform.isAndroid &&
179	        !Platform.isIOS &&
180	        !Platform.isMacOS &&
181	        !Platform.isWindows &&
182	        !Platform.isLinux) {
183	      throw UnsupportedError(
184	        'whisper_ggml supports Android, iOS, macOS, Windows, and Linux. '
185	        '${Platform.operatingSystem} has no native whisper implementation.',
186	      );
187	    }
188	    // getLibraryDirectory only exists on Apple platforms.
189	    final Directory libraryDirectory = Platform.isIOS || Platform.isMacOS
190	        ? await getLibraryDirectory()
191	        : await getApplicationSupportDirectory();
192	    return libraryDirectory.path;
193	  }
194	
195	  /// Get local path of model file
196	  Future<String> getPath(WhisperModel model) async {
197	    _dir ??= await getModelDir();
198	    return '$_dir/ggml-${model.modelName}.bin';
199	  }
200	
201	  /// Download [model] to [destinationPath]
202	  Future<String> downloadModel(WhisperModel model) async {
203	    if (!File(await getPath(model)).existsSync()) {
204	      final request = await HttpClient().getUrl(model.modelUri);
205	
206	      final response = await request.close();
207	
208	      final bytes = await consolidateHttpClientResponseBytes(response);
209	
210	      final File file = File(await getPath(model));
211	      await file.writeAsBytes(bytes);
212	
213	      return file.path;
214	    } else {
215	      return await getPath(model);
216	    }
217	  }
218	}
