14	// Global semaphore to ensure sequential calls to platform.
15	final _semaphore = Semaphore();
16	
17	/// Audio recorder for capturing audio from input devices.
18	///
19	class AudioRecorder with _AmplitudeMixin, _StateMixin, _StreamMixin {
20	  final String _recorderId;
21	
22	  Stream<RecordState>? _recordStateStream;
23	
24	  RecordPlatform get _platform => RecordPlatform.instance;
25	
26	  /// Creates a new audio recorder.
27	  AudioRecorder() : _recorderId = UuidV4.generate() {
28	    _semaphore.acquire().whenComplete(
29	          () => _platform
30	              .create(_recorderId)
31	              .whenComplete(() => _semaphore.release()),
32	        );
33	  }
34	
35	  /// Starts new recording session.
36	  ///
37	  /// [path]: The output path file. Required on all IO platforms.
38	  /// On `web`: This parameter is ignored.
39	  ///
40	  /// Output path can be retrieves when [stop] method is called.
41	  Future<void> start(RecordConfig config, {required String path}) async {
42	    await _safeCall(
43	      () {
44	        _initStateStream();
45	        return _platform.start(_recorderId, config, path: path);
46	      },
47	    );
48	  }
49	
50	  /// Starts stream recording and returns the stream.
51	  ///
52	  /// When stopping the record, you must rely on stream close event to get
53	  /// full recorded data.
54	  Future<Stream<Uint8List>> startStream(RecordConfig config) async {
55	    final stream = await _safeCall(
56	      () async {
57	        await _stopRecordStream();
58	        _initStateStream();
59	
60	        return _platform.startStream(_recorderId, config);
61	      },
62	    );
63	
64	    return _startRecordStream(stream);
65	  }
66	
67	  /// Stops recording session and release internal recorder resource.
68	  ///
69	  /// Returns the output path if any.
70	  Future<String?> stop() {
71	    return _safeCall(() async {
72	      final path = await _platform.stop(_recorderId);
73	
74	      await _stopRecordStream();
75	
76	      return path;
77	    });
78	  }
79	
80	  /// Stops and discards/deletes the file/blob.
81	  Future<void> cancel() {
82	    return _safeCall(() async {
83	      await _platform.cancel(_recorderId);
84	
85	      return _stopRecordStream();
86	    });
87	  }
88	
89	  /// Pauses recording session.
90	  Future<void> pause() {
91	    return _safeCall(() {
92	      return _platform.pause(_recorderId);
93	    });
94	  }
95	
96	  /// Resumes recording session after [pause].
97	  Future<void> resume() {
98	    return _safeCall(() {
99	      return _platform.resume(_recorderId);
100	    });
101	  }
102	
103	  /// Listen to recorder states [RecordState].
104	  ///
105	  /// Provides pause, resume and stop states.
106	  ///
107	  /// Also, you can retrieve async errors from it by adding [Function? onError] callback to the subscription.
108	  Stream<RecordState> onStateChanged() =>
109	      _recordStateStream ?? _initStateStream();
110	
111	  /// Requests for amplitude at given [interval].
112	  Stream<Amplitude> onAmplitudeChanged(Duration interval) {
113	    return _onAmplitudeChanged(interval, isRecording, getAmplitude);
114	  }
115	
116	  /// Checks if there's valid recording session.
117	  /// So if session is paused, this method will still return [true].
118	  Future<bool> isRecording() {
119	    return _safeCall(() => _platform.isRecording(_recorderId));
120	  }
121	
122	  /// Checks if recording session is paused.
123	  Future<bool> isPaused() {
124	    return _safeCall(() => _platform.isPaused(_recorderId));
125	  }
126	
127	  /// Checks and optionally requests for audio record permission.
128	  ///
129	  /// The [request] parameter controls whether to request permission if not
130	  /// already granted. Defaults to `true`.
131	  Future<bool> hasPermission({bool request = true}) {
132	    return _safeCall(
133	      () => _platform.hasPermission(_recorderId, request: request),
134	    );
135	  }
136	
137	  /// Lists capture/input devices available on the platform.
138	  ///
139	  /// On web, and in general, you should already have permission before
140	  /// accessing this method otherwise the list may return an empty list.
141	  Future<List<InputDevice>> listInputDevices() {
142	    return _safeCall(() => _platform.listInputDevices(_recorderId));
143	  }
144	
145	  /// Gets current average & max amplitudes (dBFS)
146	  /// Always returns zeros on unsupported platforms
147	  Future<Amplitude> getAmplitude() {
148	    return _safeCall(() => _platform.getAmplitude(_recorderId));
149	  }
150	
151	  /// Checks if the given encoder is supported on the current platform.
152	  Future<bool> isEncoderSupported(AudioEncoder encoder) {
153	    return _safeCall(() => _platform.isEncoderSupported(_recorderId, encoder));
154	  }
155	
156	  /// Disposes the recorder.
157	  Future<void> dispose() {
158	    return _safeCall(() async {
159	      await _disposeAmplitude();
160	      await _disposeState();
161	      await _stopRecordStream();
162	      await _platform.dispose(_recorderId);
163	    });
164	  }
165	
166	  /// iOS platform specific methods.
167	  ///
168	  /// Returns [null] when not on iOS platform.
169	  RecordIos? get ios => _platform.getIos(_recorderId);
170	
171	  Stream<RecordState> _initStateStream() {
172	    _recordStateStream ??= _onStateChanged(
173	      _platform,
174	      _recorderId,
175	      _handleAmplitudeRequesting,
176	    );
177	
178	    return _recordStateStream!;
179	  }
180	
181	  void _handleAmplitudeRequesting(RecordState state) {
182	    switch (state) {
183	      case RecordState.pause:
184	      case RecordState.stop:
185	        _stopAmplitudeMonitoring();
186	      case RecordState.record:
187	        _startAmplitudeMonitoring(isRecording, getAmplitude);
188	    }
189	  }
190	
191	  /// Safe call to [fn] with semaphore permit.
192	  Future<T> _safeCall<T>(Future<T> Function() fn) async {
193	    await _semaphore.acquire();
194	    try {
195	      return await fn();
196	    } finally {
197	      _semaphore.release();
198	    }
199	  }
200	}
