17	/// Only the transport boundary is faked (`HttpClientAdapter`), same as
18	/// `network_pipeline_integration_test.dart` — everything above it (URL
19	/// building, both real interceptors, `ApiClient`'s mapping) and below it
20	/// (real `hive_ce` write-through) is the genuine production wiring.
21	class _FakeHttpClientAdapter implements HttpClientAdapter {
22	  final List<RequestOptions> requests = [];
23	  final List<({int statusCode, Map<String, dynamic> body})> _queue = [];
24	
25	  void queueJsonResponse(int statusCode, Map<String, dynamic> body) {
26	    _queue.add((statusCode: statusCode, body: body));
27	  }
28	
29	  @override
30	  Future<ResponseBody> fetch(
31	    RequestOptions options,
32	    Stream<Uint8List>? requestStream,
33	    Future<void>? cancelFuture,
34	  ) async {
35	    requests.add(options);
36	    if (_queue.isEmpty) {
37	      throw StateError(
38	        'No queued response for ${options.method} ${options.path}',
39	      );
40	    }
41	    final next = _queue.removeAt(0);
42	    return ResponseBody.fromString(
43	      jsonEncode(next.body),
44	      next.statusCode,
45	      headers: {
46	        Headers.contentTypeHeader: [Headers.jsonContentType],
47	      },
48	    );
49	  }
50	
51	  @override
52	  void close({bool force = false}) {}
53	}
