55	/// End-to-end coverage for spec-3-1's capture flow, driven through the
56	/// real production object graph `sl` resolves for the Insertion Modal —
57	/// the exact `TextEntryCubit` instance `InsertionModal.show` would get
58	/// (`placeholder_screens.dart`'s "+" control), wired to the real
59	/// `EntriesRepositoryImpl` -> `EntriesRemoteDataSource` -> `ApiClient` ->
60	/// `Dio` (both real interceptors attached) -> a real `entries` Hive box.
61	/// Only the transport boundary and the native plugins (secure storage,
62	/// path_provider) are faked — no device/simulator/CI exists yet
63	/// (AGENTS.md) to do otherwise.
64	///
65	/// This complements rather than duplicates this story's existing tests:
66	/// `insertion_modal_test.dart`/`text_entry_cubit_test.dart` already prove
67	/// the UI/state-machine behavior against a fake `EntriesRepository`,
68	/// `entries_repository_impl_integration_test.dart` already proves the
69	/// real Hive write-through against a *mocked* datasource, and
70	/// `bootstrap_integration_test.dart` only proves the DI graph *resolves*
71	/// without ever exercising a save through it. None of them drives the
72	/// real cubit through the real network + real disk pipeline together in
73	/// one save, the way the app actually does on a "+" tap -> Salvar.
74	///
75	/// Driven directly against the cubit's own public API (`updateText`/
76	/// `save()`), not through `tester.tap`/`pumpAndSettle` on the widget tree:
77	/// `save()` here awaits genuine async I/O (a real Dio round trip, a real
78	/// Hive disk write), and `WidgetTester.pumpAndSettle()` only waits for
79	/// scheduled frames under the fake-async test clock — it isn't guaranteed
80	/// to wait for that I/O, and `runAsync` isn't a safe mix with tap/pump
81	/// (confirmed while drafting this suite: wrapping the tap in `runAsync`
82	/// broke platform-channel mocking and the request never even fired). A
83	/// plain `test()` driving the cubit directly sidesteps the whole fake-async
84	/// zone question, exactly like the other integration tests above already
85	/// do for their own real-I/O assertions.
86	void main() {
87	  TestWidgetsFlutterBinding.ensureInitialized();
88	
89	  const secureStorageChannel = MethodChannel(
90	    'plugins.it_nomads.com/flutter_secure_storage',
91	  );
92	  final fakeNativeStorage = <String, String>{};
93	
94	  Future<dynamic> handleSecureStorageCall(MethodCall call) async {
95	    final args = call.arguments as Map<dynamic, dynamic>;
96	    switch (call.method) {
97	      case 'write':
98	        fakeNativeStorage[args['key'] as String] = args['value'] as String;
99	        return null;
100	      case 'read':
101	        return fakeNativeStorage[args['key'] as String];
102	      case 'delete':
103	        fakeNativeStorage.remove(args['key'] as String);
104	        return null;
105	      case 'containsKey':
106	        return fakeNativeStorage.containsKey(args['key'] as String);
107	      default:
108	        return null;
109	    }
110	  }
111	
112	  late FakePathProviderPlatform fakePathProvider;
113	  late _FakeHttpClientAdapter adapter;
114	
115	  setUp(() async {
116	    TestDefaultBinaryMessengerBinding.instance.defaultBinaryMessenger
117	        .setMockMethodCallHandler(secureStorageChannel, handleSecureStorageCall);
118	    fakePathProvider = FakePathProviderPlatform();
119	    PathProviderPlatform.instance = fakePathProvider;
120	
121	    await resetCoreDependencies();
122	    await setupCoreDependencies();
123	
124	    // Swap only the transport boundary on the real, DI-resolved Dio
125	    // instance — both real interceptors (header + retry) stay attached.
126	    adapter = _FakeHttpClientAdapter();
127	    sl<Dio>().httpClientAdapter = adapter;
128	
129	    // `entries-create` is a bearer-required operation (not in
130	    // HeaderInterceptor.anonKeyOnlyFunctions) — seed a user access token
131	    // through the real AccessTokenProvider (backed by the faked secure
132	    // storage channel above) so the real header interceptor has one to
133	    // send.
134	    await sl<AccessTokenProvider>().saveAccessToken('e2e-test-access-token');
135	  });
136	
137	  tearDown(() async {
138	    TestDefaultBinaryMessengerBinding.instance.defaultBinaryMessenger
139	        .setMockMethodCallHandler(secureStorageChannel, null);
140	    fakeNativeStorage.clear();
141	    await Hive.close();
142	    await resetCoreDependencies();
143	    await fakePathProvider.cleanUp();
144	  });
145	
146	  test(
147	    'happy path: driving the real, DI-resolved TextEntryCubit through '
148	    'updateText + save() fires a genuine POST to entries-create with the '
149	    'right URL/headers/body, emits TextEntrySaved, and the entry really '
150	    'lands in the real entries Hive box',
151	    () async {
152	      adapter.queueJsonResponse(200, {
153	        'data': {
154	          'id': 'e2e-entry-1',
155	          'content': 'Hoje foi um bom dia.',
156	          'source': 'manual',
157	          'chatMessageId': null,
158	          'occurredAt': '2026-01-01T00:00:00Z',
159	          'serverRevision': 1,
160	          'createdAt': '2026-01-01T00:00:00Z',
161	          'updatedAt': '2026-01-01T00:00:00Z',
162	        },
163	      });
164	
165	      // The exact factory resolution `placeholder_screens.dart`'s "+"
166	      // control performs (Boundaries: a fresh instance per "+" tap).
167	      final cubit = sl<TextEntryCubit>();
168	      addTearDown(cubit.close);
169	
170	      cubit.updateText('Hoje foi um bom dia.');
171	      await cubit.save();
172	
173	      expect(cubit.state, isA<TextEntrySaved>());
174	
175	      // Exactly one real request left through the fake transport, built
176	      // by the real UrlBuilder/HeaderInterceptor, not a mock of ApiClient.
177	      expect(adapter.requests, hasLength(1));
178	      final sent = adapter.requests.single;
179	      expect(sent.path, sl<UrlBuilder>().build('entries-create'));
180	      expect(sent.data, {
181	        'content': 'Hoje foi um bom dia.',
182	        'source': 'manual',
183	      });
184	      expect(sent.headers['apikey'], dotenv.get('SUPABASE_ANON_KEY'));
185	      expect(sent.headers['Authorization'], 'Bearer e2e-test-access-token');
186	
187	      // The real write-through happened against the real Hive box.
188	      final box = sl<Box<Map>>();
189	      final stored = box.get('e2e-entry-1');
190	      expect(stored, isNotNull);
191	      expect(stored!['content'], 'Hoje foi um bom dia.');
192	      expect(stored['source'], 'manual');
193	    },
194	  );
195	
196	  test(
197	    'failure path: a non-retryable backend error (VALIDATION_ERROR) '
198	    'surfaces through the real pipeline as TextEntryError carrying '
199	    "Failure.message verbatim, fires exactly one request (no retry — "
200	    "VALIDATION_ERROR isn't one of the 6 retryable codes), and never "
201	    'writes to the real entries Hive box',
202	    () async {
203	      adapter.queueJsonResponse(400, {
204	        'code': 'VALIDATION_ERROR',
205	        'message': 'Conteúdo inválido.',
206	        'retryable': false,
207	      });
208	
209	      final cubit = sl<TextEntryCubit>();
210	      addTearDown(cubit.close);
211	
212	      cubit.updateText('Hoje foi um bom dia.');
213	      await cubit.save();
214	
215	      expect(cubit.state, isA<TextEntryError>());
216	      expect(
217	        (cubit.state as TextEntryError).message,
218	        'Conteúdo inválido.',
219	      );
220	      expect(adapter.requests, hasLength(1));
221	
222	      final box = sl<Box<Map>>();
223	      expect(box.values, isEmpty);
224	    },
225	  );
226	}
