26	/// A plain (non-mocktail) fake — same convention
27	/// `account_settings_cubit_test.dart` already uses — so a test can both
28	/// script the next `create()` result and count how many times it was
29	/// called (I/O matrix: "Cancel before save ... no `POST /entries` fires").
30	class _FakeEntriesRepository implements EntriesRepository {
31	  Either<Failure, Entry> Function()? nextResult;
32	  int createCallCount = 0;
33	
34	  /// Lets a test hold `create()` unresolved, to observe the modal's
35	  /// mid-save state (review finding: the tab bar/close button must
36	  /// disable themselves while a save is in flight).
37	  Completer<void>? gate;
38	
39	  @override
40	  Future<Either<Failure, Entry>> create({
41	    required String content,
42	    required EntrySource source,
43	  }) async {
44	    createCallCount++;
45	    final activeGate = gate;
46	    if (activeGate != null) {
47	      await activeGate.future;
48	    }
49	    return nextResult!();
50	  }
51	}
