9	/// Class used to convert any audio file to wav
10	class WhisperAudioConvert {
11	  ///
12	  const WhisperAudioConvert({
13	    required this.audioInput,
14	    required this.audioOutput,
15	  });
16	
17	  /// Input audio file
18	  final File audioInput;
19	
20	  /// Output audio file
21	  /// Overwriten if already exist
22	  final File audioOutput;
23	
24	  /// convert [audioInput] to wav file
25	  Future<File?> convert() async {
26	    if (Platform.isWindows || Platform.isLinux) {
27	      return _convertWithFfmpegCli();
28	    }
29	
30	    final FFmpegSession session = await FFmpegKit.execute(
31	      [
32	        '-y',
33	        '-i',
34	        audioInput.path,
35	        '-ar',
36	        '16000',
37	        '-ac',
38	        '1',
39	        '-c:a',
40	        'pcm_s16le',
41	        audioOutput.path,
42	      ].join(' '),
43	    );
44	
45	    final ReturnCode? returnCode = await session.getReturnCode();
46	
47	    if (ReturnCode.isSuccess(returnCode)) {
48	      return audioOutput;
49	    } else if (ReturnCode.isCancel(returnCode)) {
50	      debugPrint('File convertion canceled');
51	    } else {
52	      debugPrint(
53	        'File convertion error with returnCode ${returnCode?.getValue()}',
54	      );
55	    }
56	
57	    return null;
58	  }
59	
60	  /// ffmpeg_kit has no Windows or Linux implementation, so those platforms
61	  /// use an `ffmpeg` executable from PATH instead. Returns null when ffmpeg
62	  /// is missing or fails; callers then transcribe the original file, which
63	  /// works as long as it is already a 16 kHz mono WAV.
64	  Future<File?> _convertWithFfmpegCli() async {
65	    try {
66	      final ProcessResult result = await Process.run('ffmpeg', [
67	        '-y',
68	        '-i',
69	        audioInput.path,
70	        '-ar',
71	        '16000',
72	        '-ac',
73	        '1',
74	        '-c:a',
75	        'pcm_s16le',
76	        audioOutput.path,
77	      ]);
78	      if (result.exitCode == 0) {
79	        return audioOutput;
80	      }
81	      debugPrint(
82	        'File convertion error with exitCode ${result.exitCode}: '
83	        '${result.stderr}',
84	      );
85	    } on ProcessException {
86	      debugPrint(
87	        'ffmpeg not found on PATH; passing audio through unconverted. '
88	        'Input must be a 16 kHz mono WAV.',
89	      );
90	    }
91	    return null;
92	  }
93	}
