        TextField(
          controller: controller,
          enabled: !isSaving,
          minLines: 3,
          maxLines: null,
          // Mirrors `POST /entries`'s own `content` cap
          // (`openapi.yaml`: `maxLength: 20000`) — avoids an avoidable
