/// Covers both `AudioError` shapes (I/O matrix): [hasFile] false means
/// permission was denied before any recording existed ("no file to
/// preserve") — [canRetry] is then always true, re-requesting permission.
/// [hasFile] true with [canRetry] true means transcription itself failed
/// (file preserved, re-transcribed in place). [canRetry] false means a
/// *save* failure from `AudioTranscribed` — the text field stays editable
/// with Salvar re-enabled instead of a "Tentar novamente" control,
/// mirroring `_TextoTab`'s own `TextEntryError` rendering.
class _AudioErrorView extends StatelessWidget {
  const _AudioErrorView({
    required this.controller,
    required this.message,
    required this.canRetry,
    required this.hasFile,
  });

  final TextEditingController controller;
  final String message;
  final bool canRetry;
  final bool hasFile;

  @override
  Widget build(BuildContext context) {
    if (canRetry) {
      return Column(
        mainAxisSize: MainAxisSize.min,
        children: [
          Icon(Icons.error_outline, color: DesignTokens.colorError),
          const SizedBox(height: DesignTokens.spacingSm),
          Text(
            message,
            textAlign: TextAlign.center,
            style: DesignTokens.textBodyMd.copyWith(
              color: DesignTokens.colorError,
            ),
          ),
          const SizedBox(height: DesignTokens.spacingMd),
          AppButton(
            label: 'Tentar novamente',
            onPressed: () => context.read<AudioEntryCubit>().retry(),
          ),
        ],
      );
    }
    final canSave = controller.text.trim().isNotEmpty;
    return Column(
      mainAxisSize: MainAxisSize.min,
      crossAxisAlignment: CrossAxisAlignment.stretch,
      children: [
        TextField(
          controller: controller,
          minLines: 3,
          maxLines: null,
          maxLength: 20000,
          onChanged: (value) =>
              context.read<AudioEntryCubit>().updateText(value),
          style: DesignTokens.textBodyLg.copyWith(
            color: DesignTokens.colorTextPrimary,
          ),
          decoration: const InputDecoration(
            counterText: '',
            contentPadding: DesignTokens.textFieldContentPadding,
            border: OutlineInputBorder(
              borderRadius: BorderRadius.all(
                Radius.circular(DesignTokens.radiusSm),
              ),
              borderSide: BorderSide(
                color: DesignTokens.colorBorder,
                width: DesignTokens.borderWidthDefault,
              ),
            ),
          ),
        ),
        const SizedBox(height: DesignTokens.spacingSm),
        Text(
          message,
          style: DesignTokens.textBodyMd.copyWith(color: DesignTokens.colorError),
        ),
        const SizedBox(height: DesignTokens.spacingMd),
        AppButton(
          label: 'Salvar',
          onPressed: canSave
              ? () => context.read<AudioEntryCubit>().save()
              : null,
        ),
      ],
    );
  }
}

/// A live (or frozen) amplitude-bar waveform. `amplitudeStream == null`
/// renders a static placeholder pattern at [opacity] instead of
/// subscribing — the "frozen" rendering `_AudioProcessingView` uses.
class _Waveform extends StatefulWidget {
  const _Waveform({required this.amplitudeStream, required this.opacity});

  final Stream<double>? amplitudeStream;
  final double opacity;

  @override
  State<_Waveform> createState() => _WaveformState();
}

class _WaveformState extends State<_Waveform> {
  final List<double> _samples = List.filled(_waveformBarCount, 0.1);
  StreamSubscription<double>? _subscription;

  @override
  void initState() {
    super.initState();
    _subscription = widget.amplitudeStream?.listen((amplitude) {
      if (!mounted) {
        return;
      }
      setState(() {
        _samples.removeAt(0);
        _samples.add(amplitude.clamp(0.1, 1.0));
      });
    });
  }

  @override
  void dispose() {
    _subscription?.cancel();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return Opacity(
      opacity: widget.opacity,
      child: SizedBox(
        height: DesignTokens.spacing2xl,
        child: Row(
          mainAxisAlignment: MainAxisAlignment.center,
          crossAxisAlignment: CrossAxisAlignment.center,
          children: [
            for (var i = 0; i < _samples.length; i++) ...[
              AnimatedContainer(
                duration: DesignTokens.durationSheetUp,
                width: DesignTokens.spacingXs,
                height: DesignTokens.spacing2xl * _samples[i],
                decoration: const BoxDecoration(
                  color: DesignTokens.colorError,
                  borderRadius: BorderRadius.all(
                    Radius.circular(DesignTokens.radiusFull),
                  ),
                ),
              ),
              if (i < _samples.length - 1)
                const SizedBox(width: DesignTokens.spacingXs),
            ],
          ],
        ),
      ),
    );
  }
}

