12	/// The Insertion Modal — a 3-tab bottom sheet (Texto/Áudio/Foto) opened
13	/// from the Home/Chat "+" control (`placeholder_screens.dart`). Texto and
14	/// Áudio are both functional as of spec-3-2 (Boundaries) — Foto still
15	/// renders its own idle, non-interactive placeholder (Story 3.3).
16	class InsertionModal extends StatelessWidget {
17	  const InsertionModal({required this.cubit, required this.audioCubit, super.key});
18	
19	  final TextEntryCubit cubit;
20	  final AudioEntryCubit audioCubit;
21	
22	  /// Presents the modal exactly as the Boundaries dictate:
23	  /// `showModalBottomSheet(isScrollControlled: true, barrierColor:
24	  /// colorScrimHeavy)`, `radiusLg` top corners + `elevation2` (drawn by
25	  /// this widget's own `Container`, not Material's `elevation` double —
26	  /// same convention `ConfirmationDialog`'s card already uses), and a
27	  /// `durationSheetUp` entrance that collapses to zero under Reduce
28	  /// Motion (`MediaQuery.disableAnimations`).
29	  ///
30	  /// [cubit]/[audioCubit] are both fresh, `get_it`-factory-scoped
31	  /// instances — one pair per "+" tap (Boundaries: "Modal open resets") —
32	  /// closed here once the sheet is gone, regardless of how it closed
33	  /// (Salvar success, "x", swipe-down, or barrier dismiss) — the caller
34	  /// never has to remember to do this itself.
35	  static Future<void> show(
36	    BuildContext context, {
37	    required TextEntryCubit cubit,
38	    required AudioEntryCubit audioCubit,
39	  }) async {
40	    final reduceMotion = MediaQuery.of(context).disableAnimations;
41	    final controller =
42	        BottomSheet.createAnimationController(Navigator.of(context))
43	          ..duration = reduceMotion
44	              ? Duration.zero
45	              : DesignTokens.durationSheetUp
46	          // Boundaries only names the entrance, but Reduce Motion should
47	          // collapse the exit the same way — otherwise dismissing the
48	          // sheet would still animate for anyone who asked for no motion.
49	          ..reverseDuration = reduceMotion ? Duration.zero : null;
50	    try {
51	      await showModalBottomSheet<void>(
52	        context: context,
53	        isScrollControlled: true,
54	        barrierColor: DesignTokens.colorScrimHeavy,
55	        backgroundColor: Colors.transparent,
56	        elevation: 0,
57	        transitionAnimationController: controller,
58	        builder: (_) => InsertionModal(cubit: cubit, audioCubit: audioCubit),
59	      );
60	    } finally {
61	      // `showModalBottomSheet`'s own Future completes as soon as the
62	      // route is popped — *before* the exit (`reverse()`) animation the
63	      // framework drives on this same controller actually finishes.
64	      // Disposing immediately would cancel that animation's ticker
65	      // mid-flight, permanently freezing the sheet on screen (its
66	      // `AnimatedBuilder` keeps rendering the controller's last value,
67	      // and the route itself never reaches `AnimationStatus.dismissed`
68	      // to be removed from the `Overlay`). Documented behavior
69	      // (`BottomSheet.transitionAnimationController`'s own doc: "the
70	      // caller is responsible for disposing it when the controller is
71	      // no longer needed") — waiting for `dismissed` first is that
72	      // "no longer needed" point.
73	      if (!controller.isDismissed) {
74	        final animationDone = Completer<void>();
75	        void onStatusChange(AnimationStatus status) {
76	          if (status == AnimationStatus.dismissed) {
77	            animationDone.complete();
78	          }
79	        }
80	
81	        controller.addStatusListener(onStatusChange);
82	        await animationDone.future;
83	        controller.removeStatusListener(onStatusChange);
84	      }
85	      controller.dispose();
86	      await cubit.close();
87	      await audioCubit.close();
88	    }
89	  }
90	
91	  @override
92	  Widget build(BuildContext context) {
93	    return MultiBlocProvider(
94	      providers: [
95	        BlocProvider.value(value: cubit),
96	        BlocProvider.value(value: audioCubit),
97	      ],
98	      child: const _InsertionModalBody(),
99	    );
100	  }
101	}
102	
103	/// Coarse `AudioCaptureState` discriminator used only to decide whether a
104	/// given emission is a genuine transition worth announcing — e.g.
105	/// [AudioRecording]'s own per-second timer tick re-emits the same kind
106	/// repeatedly and must never re-announce "Gravando áudio" every second.
107	enum _AudioAnnounceKind { idle, recording, processing, transcribed, saving, saved, error }
108	
109	_AudioAnnounceKind _audioAnnounceKindOf(AudioCaptureState state) => switch (state) {
110	  AudioIdle() => _AudioAnnounceKind.idle,
111	  AudioRecording() => _AudioAnnounceKind.recording,
112	  AudioProcessing() => _AudioAnnounceKind.processing,
113	  AudioTranscribed(saving: true) => _AudioAnnounceKind.saving,
114	  AudioTranscribed() => _AudioAnnounceKind.transcribed,
115	  AudioSaved() => _AudioAnnounceKind.saved,
116	  AudioError() => _AudioAnnounceKind.error,
117	};
118	
119	class _InsertionModalBody extends StatefulWidget {
120	  const _InsertionModalBody();
121	
122	  @override
123	  State<_InsertionModalBody> createState() => _InsertionModalBodyState();
124	}
125	
126	class _InsertionModalBodyState extends State<_InsertionModalBody> {
127	  final _textController = TextEditingController();
128	
129	  /// The Áudio tab's own text field controller — lifted up here rather
130	  /// than owned by `_AudioTab` itself so it survives `_AudioTab` being
131	  /// rebuilt on every `AudioCaptureState` change without losing cursor
132	  /// position/focus, same rationale as [_textController] living here
133	  /// instead of inside `_TextoTab`.
134	  final _audioTextController = TextEditingController();
135

135	
136	  /// The last `AudioTranscribed.path` this controller's text was synced
137	  /// from — only a *new* transcription (a different/first path) resets
138	  /// the controller's text; the user's own edits via `onChanged` never
139	  /// get clobbered by an unrelated rebuild.
140	  String? _lastSyncedAudioPath;
141	
142	  /// Tracks the previously-seen `activeTab` so the listener can tell a
143	  /// genuine tab switch apart from the many other `TextEntryIdle`
144	  /// emissions a keystroke produces (`updateText` also emits `Idle`) —
145	  /// initialized from the cubit's own current state so the very first
146	  /// comparison (before any emission the listener sees) is still correct.
147	  late CaptureTab _lastAnnouncedTab;
148	
149	  /// Same "only announce a genuine transition" guard as [_lastAnnouncedTab],
150	  /// for `AudioEntryCubit` (see [_audioAnnounceKindOf]).
151	  late _AudioAnnounceKind _lastAudioAnnouncedKind;
152	
153	  @override
154	  void initState() {
155	    super.initState();
156	    _lastAnnouncedTab = context.read<TextEntryCubit>().state.activeTab;
157	    _lastAudioAnnouncedKind = _audioAnnounceKindOf(
158	      context.read<AudioEntryCubit>().state,
159	    );
160	  }
161	
162	  @override
163	  void dispose() {
164	    _textController.dispose();
165	    _audioTextController.dispose();
166	    super.dispose();
167	  }
168	
169	  // Labels for the 3 tabs, shared between the announcement below and
170	  // `_TabBar`'s own rendering (`_TabBar._tabs`) — kept here too since
171	  // `selectTab`'s announcement needs the label for whichever tab the
172	  // user just switched *to*, not the cubit's own (enum-only) state.
173	  static const _tabLabels = {
174	    CaptureTab.texto: 'Texto',
175	    CaptureTab.audio: 'Áudio',
176	    CaptureTab.foto: 'Foto',
177	  };
178	
179	  // Mirrors `account_settings_screen.dart`'s own `_announce` — VoiceOver
180	  // (this app is iOS-only) doesn't reliably treat a live-region subtree
181	  // update as an announcement on its own, so every state change this
182	  // story introduces — saving, success, failure, and a tab switch — is
183	  // spoken explicitly here instead (Acceptance Criteria: "no
184	  // color/animation alone").
185	  Future<void> _announce(String message) async {
186	    if (!mounted) {
187	      return;
188	    }
189	    await SemanticsService.sendAnnouncement(
190	      View.of(context),
191	      message,
192	      TextDirection.ltr,
193	    );
194	  }
195	
196	  void _onTextEntryStateChange(BuildContext context, TextEntryState state) {
197	    // Review finding: a tab switch (re-emitted as `TextEntryIdle`,
198	    // same as every keystroke) previously went unannounced —
199	    // detected here by comparing against the last tab seen, so a
200	    // plain keystroke (same `activeTab`) never re-triggers it.
201	    if (state.activeTab != _lastAnnouncedTab) {
202	      final previousTab = _lastAnnouncedTab;
203	      _lastAnnouncedTab = state.activeTab;
204	      _announce('Aba ${_tabLabels[state.activeTab]} selecionada');
205	      // spec-3-2's Code Map: tab-switch detection also drives
206	      // `AudioEntryCubit.startRecording()`/`.cancel()` — entering Áudio
207	      // starts recording immediately (Acceptance Criteria), leaving it
208	      // stops/releases the recorder (I/O matrix: "Leave tab
209	      // mid-recording"), never the full Story 3.4 cancel choreography.
210	      final audioCubit = context.read<AudioEntryCubit>();
211	      if (state.activeTab == CaptureTab.audio) {
212	        unawaited(audioCubit.startRecording());
213	      } else if (previousTab == CaptureTab.audio) {
214	        unawaited(audioCubit.cancel());
215	      }
216	    }
217	    switch (state) {
218	      case TextEntrySaved():
219	        // I/O matrix: "success closes the modal". Review finding:
220	        // wait for the announcement to actually be sent before
221	        // popping — previously fired-and-forgot in the same tick,
222	        // risking the announcement being cut off by the dismiss
223	        // transition.
224	        unawaited(
225	          _announce('Registro salvo').then((_) {
226	            if (context.mounted) {
227	              Navigator.of(context).pop();
228	            }
229	          }),
230	        );
231	      case TextEntrySaving():
232	        _announce('Salvando registro');
233	      case TextEntryError():
234	        _announce(state.message);
235	      case TextEntryIdle():
236	        break;
237	    }
238	  }
239	
240	  void _onAudioStateChange(BuildContext context, AudioCaptureState state) {
241	    if (state is AudioTranscribed && state.path != _lastSyncedAudioPath) {
242	      _lastSyncedAudioPath = state.path;
243	      _audioTextController.text = state.text;
244	    }
245	    final kind = _audioAnnounceKindOf(state);
246	    if (kind == _lastAudioAnnouncedKind) {
247	      return;
248	    }
249	    _lastAudioAnnouncedKind = kind;
250	    switch (state) {
251	      case AudioRecording():
252	        _announce('Gravando áudio');
253	      case AudioProcessing():
254	        _announce('Transcrevendo áudio');
255	      case AudioTranscribed(saving: true):
256	        _announce('Salvando registro');
257	      case AudioTranscribed():
258	        _announce('Transcrição concluída. Revise o texto antes de salvar.');
259	      case AudioError(message: final message):
260	        _announce(message);
261	      case AudioSaved():
262	        // Same "wait for the announcement" rationale as
263	        // `TextEntrySaved` above.
264	        unawaited(
265	          _announce('Registro salvo').then((_) {
266	            if (context.mounted) {
267	              Navigator.of(context).pop();
268	            }
269	          }),
270	        );
271	      case AudioIdle():
272	        break;
273	    }
274	  }
275	
276	  @override
277	  Widget build(BuildContext context) {
278	    return BlocListener<AudioEntryCubit, AudioCaptureState>(
279	      listener: _onAudioStateChange,
280	      child: BlocConsumer<TextEntryCubit, TextEntryState>(
281	        listener: _onTextEntryStateChange,
282	        builder: (context, state) {
283	          final isSaving = state is TextEntrySaving;
284	          return Container(
285	            padding: DesignTokens.screenPadding,
286	            decoration: const BoxDecoration(
287	              color: DesignTokens.colorSurfaceElevated,
288	              borderRadius: BorderRadius.vertical(
289	                top: Radius.circular(DesignTokens.radiusLg),
290	              ),
291	              boxShadow: DesignTokens.elevation2,
292	            ),
293	            child: Padding(
294	              // Keeps the Texto field clear of the on-screen keyboard — the
295	              // sheet is `isScrollControlled: true`, so it already grows to
296	              // fit; this is the standard companion fix for the keyboard
297	              // inset itself.
298	              padding: EdgeInsets.only(
299	                bottom: MediaQuery.of(context).viewInsets.bottom,
300	              ),
301	              child: SafeArea(
302	                top: false,
303	                child: Column(
304	                  mainAxisSize: MainAxisSize.min,
305	                  crossAxisAlignment: CrossAxisAlignment.stretch,
306	                  children: [
307	                    Row(
308	                      crossAxisAlignment: CrossAxisAlignment.center,
309	                      children: [
310	                        Expanded(
311	                          child: _TabBar(
312	                            activeTab: state.activeTab,
313	                            isSaving: isSaving,
314	                          ),
315	                        ),
316	                        const SizedBox(width: DesignTokens.spacingSm),
317	                        _CloseButton(isSaving: isSaving),
318	                      ],
319	                    ),
320	                    const SizedBox(height: DesignTokens.spacingMd),
321	                    switch (state.activeTab) {
322	                      CaptureTab.texto => _TextoTab(
323	                        controller: _textController,
324	                        state: state,
325	                      ),
326	                      CaptureTab.audio => _AudioTab(
327	                        controller: _audioTextController,
328	                      ),
329	                      CaptureTab.foto => const _IdleTabPlaceholder(
330	                        icon: Icons.photo_camera_outlined,
331	                        label: 'Foto chega em breve',
332	                      ),
333	                    },
334	                  ],
335	                ),
336	              ),
337	            ),
338	          );
339	        },

