13	/// Registers the `capture` feature into the project's single `get_it`
14	/// instance (`sl`). Unlike every other feature's cubit in this codebase
15	/// (`AccountSettingsCubit`/`AuthCubit`, lazy singletons), [TextEntryCubit]/
16	/// [AudioEntryCubit] are both **factories** — the Insertion Modal needs a
17	/// fresh instance of each per "+" tap (Boundaries: "Modal open resets"),
18	/// not one long-lived instance reused across opens. [MicRecorder]/
19	/// [AudioTranscriber] (and the raw `record`/`whisper_ggml` plugin
20	/// instances underneath them) stay lazy singletons instead — one real
21	/// recorder/transcriber for the app's lifetime, shared across every modal
22	/// open, mirroring `EntriesRepository`'s own registration shape. Called
23	/// from `setupCoreDependencies()` right after `registerEntriesFeature()`
24	/// (Code Map).
25	void registerCaptureFeature() {
26	  sl.registerFactory<TextEntryCubit>(
27	    () => TextEntryCubit(sl<EntriesRepository>()),
28	  );
29	
30	  sl.registerLazySingleton<record_pkg.AudioRecorder>(
31	    record_pkg.AudioRecorder.new,
32	  );
33	  sl.registerLazySingleton<MicRecorder>(
34	    () => RecordMicRecorder(recorder: sl<record_pkg.AudioRecorder>()),
35	  );
36	
37	  sl.registerLazySingleton<WhisperController>(WhisperController.new);
38	  sl.registerLazySingleton<AudioTranscriber>(
39	    () => WhisperAudioTranscriber(controller: sl<WhisperController>()),
40	  );
41	
42	  sl.registerFactory<AudioEntryCubit>(
43	    () => AudioEntryCubit(
44	      sl<MicRecorder>(),
45	      sl<AudioTranscriber>(),
46	      sl<EntriesRepository>(),
47	    ),
48	  );
49	}
