5	/// Stands in for the real `path_provider` plugin wherever
6	/// `Hive.initFlutter()` (first exercised by Story 3.1's
7	/// `registerEntriesFeature()`, transitively via `hive_ce_flutter`) runs
8	/// under `flutter test` — no device/simulator exists yet (AGENTS.md) to
9	/// answer `getApplicationDocumentsPath()` for real. Returns a fresh temp
10	/// directory per call instead, same "fake the native platform channel"
11	/// rationale `bootstrap_integration_test.dart`/`main_test.dart` already
12	/// apply to `flutter_secure_storage`.
13	///
14	/// Review finding: a temp directory created here is real disk state, not
15	/// an in-memory fake — without [cleanUp], every test run exercising DI
16	/// bootstrap leaks one orphaned folder under the OS temp dir per `setUp()`
17	/// call. Callers are expected to hold on to the instance they assign to
18	/// `PathProviderPlatform.instance` and call [cleanUp] from their own
19	/// `tearDown`.
20	class FakePathProviderPlatform extends PathProviderPlatform {
21	  final List<Directory> _createdDirectories = [];
22	
23	  @override
24	  Future<String?> getApplicationDocumentsPath() async {
25	    final dir = Directory.systemTemp.createTempSync('cerne_test_hive_');
26	    _createdDirectories.add(dir);
27	    return dir.path;
28	  }
29	
30	  /// Deletes every temp directory this instance created. Safe to call
31	  /// even if nothing was ever created, and even if a directory was
32	  /// already removed by something else.
33	  Future<void> cleanUp() async {
34	    for (final dir in _createdDirectories) {
35	      try {
36	        if (await dir.exists()) {
37	          await dir.delete(recursive: true);
38	        }
39	      } catch (_) {
40	        // Best-effort cleanup — a leftover temp folder is a minor local
41	        // annoyance, never a reason to fail the test that asked for it.
42	      }
43	    }
44	    _createdDirectories.clear();
45	  }
46	}
