      final firstSave = cubit.save();
      await cubit.save();

      verify(
        () => mockRepository.create(
          content: any(named: 'content'),
          source: any(named: 'source'),
          mediaDurationSeconds: any(named: 'mediaDurationSeconds'),
        ),
      ).called(1);

